window.location.href = `/api/lab-results/download/?file=${patientId}_result.pdf&token=${token}`;
}
runExport() {
this.http.get(`/api/reports/export/?type=${this.exportType}`)
.subscribe((res: any) => {
this.exportOutput = res.output;
});
}
}
